    @Override protected void onDestroy(){epoch++;if(guideWindow!=null)guideWindow.dismiss();if(appearanceWindow!=null)appearanceWindow.dismiss();if(activeDialog!=null)activeDialog.dismiss();worker.shutdownNow();super.onDestroy();}
