    void applyPalette(){
        String mode=prefs.getString("appearance","system");dark="dark".equals(mode)||"system".equals(mode)&&(getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES;
        INK=dark?0xfff4f6fc:0xff202329;MUTED=dark?0xffaab4c7:0xff5e6574;BLUE=dark?0xff8ca8ff:0xff2d56e8;BORDER=dark?0xff323c4e:0xffe2e5ec;CANVAS=dark?0xff1d2330:0xfff7f8fa;SOFT=dark?0xff223151:0xffedf2ff;WHITE=dark?0xff141821:0xffffffff;
    }
    int semantic(int color){if(!dark)return color;if(color==0xff287347)return 0xff80dfae;if(color==0xffa43b35)return 0xffffa49b;if(color==0xffeaf6ee)return 0xff173c2d;return color;}
