    void roundDialog(Dialog d){activeDialog=d;if(d.getWindow()!=null){UiMotion.enter(d.getWindow().getDecorView());d.getWindow().setBackgroundDrawable(shape(CANVAS,24,true));d.getWindow().setDimAmount(.46f);}if(d instanceof AlertDialog){AlertDialog a=(AlertDialog)d;for(int id:new int[]{-1,-2,-3})if(a.getButton(id)!=null)a.getButton(id).setTextColor(BLUE);}}
    void appearance(){Dialog d=new Dialog(dialogContext());appearanceWindow=d;LinearLayout panel=vertical();panel.setPadding(dp(24),dp(24),dp(24),dp(24));panel.setBackground(shape(CANVAS,24,true));addText(panel,"Make it your workspace",22,true,INK,8);addText(panel,"Choose the appearance for every screen, menu and guide.",14,false,MUTED,18);String current=prefs.getString("appearance","system");for(String mode:new String[]{"system","light","dark"}){String label=mode.equals("system")?"Follow device":"Light";if(mode.equals("dark"))label="Dark";panel.addView(button(label+(current.equals(mode)?"  ✓":""),current.equals(mode),()->{d.dismiss();setAppearance(mode);}));gap(panel,8);}CheckBox reduce=new CheckBox(dialogContext());reduce.setText("Reduce motion");reduce.setTextSize(14);reduce.setTextColor(INK);reduce.setButtonTintList(android.content.res.ColorStateList.valueOf(BLUE));reduce.setChecked(prefs.getBoolean("reduceMotion",false));reduce.setOnCheckedChangeListener((v,checked)->prefs.edit().putBoolean("reduceMotion",checked).apply());panel.addView(reduce);panel.addView(button(prefs.getBoolean("compactUi",true)?"UI size: Compact":"UI size: Comfortable",false,()->{prefs.edit().putBoolean("compactUi",!prefs.getBoolean("compactUi",true)).apply();d.dismiss();render();}));d.setContentView(panel);d.show();d.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));d.getWindow().setLayout(Math.min(dp(400),getResources().getDisplayMetrics().widthPixels-dp(48)),-2);}
