    void applySafeInsets(View view){if(Build.VERSION.SDK_INT>=35){view.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);return insets;});view.requestApplyInsets();}}
    void restore(){busy=true;render();int token=epoch;worker.execute(()->{try{String key=vault.load();if(key==null){runOnUiThread(()->{if(token==epoch){busy=false;render();}});return;}RobloxApi.Session s=api.login(key);runOnUiThread(()->{if(token==epoch)connected(s);});}catch(Exception e){runOnUiThread(()->{if(token==epoch){busy=false;loginError="Saved connection could not be verified. "+RobloxApi.safe(e);render();}});}});}
    void connected(RobloxApi.Session s){session=s;busy=false;loginError="";screen="home";render();scan();refreshCloud();}
    void navigate(String next){screen=next;render();if(next.equals("projects")||next.equals("home"))scan();if(next.equals("cloud")&&session!=null&&listing==null&&!loadingCloud)refreshCloud();}
    void render(){
        if(isFinishing())return;
        applyPalette();setTheme(dark?R.style.AppThemeDark:R.style.AppTheme);applySystemBars();
        if(screen.equals("login"))getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);
        root=vertical();root.setBackgroundColor(WHITE);applySafeInsets(root);setContentView(root);header=horizontal();header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(14),0,dp(10),0);root.addView(header,new LinearLayout.LayoutParams(-1,dp(38)));
        StudioIcon mark=new StudioIcon(this,"logo",INK);header.addView(mark,new LinearLayout.LayoutParams(dp(22),dp(22)));
        TextView brand=text("Studio Mobile",13.5f,true,INK);marginAdd(header,brand,10,0);
        spacer(header);header.addView(iconAction(dark?"sun":"moon","Appearance settings",()->appearance()),new LinearLayout.LayoutParams(dp(36),dp(36)));
        if(screen.equals("setup")||screen.equals("login")){header.addView(text("SETUP",10,true,MUTED),inner(dp(8),0));}
        else {
            header.addView(iconAction("download","Import from Roblox",()->navigate("cloud")),new LinearLayout.LayoutParams(dp(36),dp(36)));
            View separator=new View(this);separator.setBackgroundColor(BORDER);LinearLayout.LayoutParams line=new LinearLayout.LayoutParams(dp(1),dp(20));line.setMargins(dp(6),0,dp(8),0);header.addView(separator,line);
            LinearLayout profile=horizontal();profile.setGravity(Gravity.CENTER_VERTICAL);profile.setPadding(dp(4),0,dp(4),0);
            if(session!=null){ImageView image=avatar(session.avatar,28);profile.addView(image,new LinearLayout.LayoutParams(dp(26),dp(26)));TextView username=text(session.username,12.5f,true,INK);username.setMaxWidth(dp(140));username.setSingleLine(true);username.setEllipsize(TextUtils.TruncateAt.END);marginAdd(profile,username,7,0);StudioIcon chev=new StudioIcon(this,"chevron",MUTED);marginAdd(profile,chev,6,0,16,16);profile.setOnClickListener(v->profileMenu(profile));profile.setContentDescription("Account menu for "+session.username);}
            else{profile.addView(text("Connect account",12.5f,true,BLUE));profile.setOnClickListener(v->navigate("login"));}
            profile.setMinimumHeight(dp(36));profile.setBackground(ripple(WHITE,6));header.addView(profile);
        }
        divider(root);body=horizontal();root.addView(body,new LinearLayout.LayoutParams(-1,0,1));
        if(screen.equals("setup")){content=page(body);setupPage();finishScene();return;}
        if(screen.equals("login")){content=page(body);loginPage();finishScene();return;}
        sidebar();work=new FrameLayout(this);work.setBackgroundColor(WHITE);body.addView(work,new LinearLayout.LayoutParams(0,-1,1));content=page(work);
        switch(screen){case "home":homePage();break;case "projects":projectsPage();break;case "cloud":cloudPage();break;case "new-project":projectUi.form(false);break;case "project-settings":projectUi.form(true);break;case "project":projectUi.detail();break;}finishScene();
    }
